sourcesContent:
import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';

import Header from '../components/Header';
import Footer from '../components/Footer';

import javaLogo from '../assets/Java-Logo.png';
import pythonLogo from '../assets/python logo.jpeg';
import javaFullStack from '../assets/java-fullstack.jpg';
import pythonFullStack from '../assets/python full stack.jpeg';
import mernStack from '../assets/mernstack.jpg';
import dataAnalytics from '../assets/data analytics.jpeg';
import genaiLogo from '../assets/genai logo.png';

const courseData = [
  {
    title: 'Java Development',
    image: javaLogo,
    category: 'Development',
    badge: 'Popular',
    description:
      'Build strong programming fundamentals and enterprise applications.',
    topics: [
      'Core Java',
      'OOP Concepts',
      'Collections & Generics',
      'Multithreading',
      'JDBC & Servlets'
    ],
    duration: '3 – 4 Months',
    level: 'Beginner to Advanced',
    mode: 'Online + Live Classes',
    overview:
      'Master Java programming from fundamentals to advanced concepts and build strong enterprise development skills.',
    modules: [
      {
        title: 'Java Fundamentals',
        content:
          'Learn Java syntax, variables, data types, operators, input/output, control statements and the fundamentals required to start Java programming.'
      },
      {
        title: 'Object-Oriented Programming',
        content:
          'Understand classes, objects, inheritance, polymorphism, abstraction, encapsulation, constructors and interfaces with practical examples.'
      },
      {
        title: 'Collections Framework',
        content:
          'Learn List, Set, Map, Queue, ArrayList, LinkedList, HashSet, TreeSet, HashMap and other important Java collection concepts.'
      },
      {
        title: 'Exception Handling',
        content:
          'Understand exceptions, try-catch, finally, throw, throws, custom exceptions and best practices for handling application errors.'
      },
      {
        title: 'Multithreading',
        content:
          'Learn threads, thread lifecycle, synchronization, thread communication, ExecutorService and practical multithreading concepts.'
      },
      {
        title: 'JDBC & Servlets',
        content:
          'Connect Java applications with databases using JDBC and understand servlet fundamentals, request handling and response processing.'
      },
      {
        title: 'Mini Projects',
        content:
          'Build practical Java mini projects to apply programming, OOP, database and application development concepts.'
      },
      {
        title: 'Final Project',
        content:
          'Develop a complete real-world Java project using the concepts learned throughout the course.'
      }
    ]
  },

  {
    title: 'Python Development',
    image: pythonLogo,
    category: 'Development',
    description:
      'Learn Python for real-world applications, automation and more.',
    topics: [
      'Python Basics',
      'Data Structures',
      'OOP in Python',
      'File Handling',
      'Libraries & Projects'
    ],
    duration: '3 – 4 Months',
    level: 'Beginner to Advanced',
    mode: 'Online + Live Classes',
    overview:
      'Learn Python from the ground up and develop practical programming, automation and application-building skills.',
    modules: [
      {
        title: 'Python Fundamentals',
        content:
          'Learn Python syntax, variables, data types, operators, input/output and the basic programming concepts needed to build Python applications.'
      },
      {
        title: 'Variables & Data Types',
        content:
          'Understand numbers, strings, lists, tuples, sets, dictionaries, type conversion and Python data handling.'
      },
      {
        title: 'Control Statements',
        content:
          'Learn if, elif, else, for loops, while loops, break, continue and nested control structures.'
      },
      {
        title: 'Functions',
        content:
          'Create reusable functions and learn parameters, return values, lambda functions, scope and advanced function concepts.'
      },
      {
        title: 'Object-Oriented Programming',
        content:
          'Learn classes, objects, inheritance, encapsulation, polymorphism, constructors and abstraction in Python.'
      },
      {
        title: 'File Handling',
        content:
          'Read, write and manage files using Python and understand CSV, JSON and other common data formats.'
      },
      {
        title: 'Python Libraries',
        content:
          'Work with commonly used Python libraries and understand how external packages can be used in real-world projects.'
      },
      {
        title: 'Projects',
        content:
          'Build practical Python projects to strengthen programming, problem-solving and application development skills.'
      }
    ]
  },

  {
    title: 'Java Full Stack',
    image: javaFullStack,
    category: 'Full Stack',
    description:
      'Become a complete developer with frontend, backend and database skills.',
    topics: [
      'Core Java',
      'Spring Boot',
      'HTML, CSS, JavaScript',
      'React (Frontend)',
      'MySQL & Real-Time Projects'
    ],
    duration: '6 – 8 Months',
    level: 'Intermediate to Advanced',
    mode: 'Online + Live Classes',
    overview:
      'Become a complete Java Full Stack Developer by learning frontend, backend, databases and real-world project development.',
    modules: [
      {
        title: 'Core Java',
        content:
          'Master Java fundamentals, OOP, collections, exception handling, multithreading and modern Java programming concepts.'
      },
      {
        title: 'Advanced Java',
        content:
          'Learn advanced Java programming, JDBC, Servlets and backend development fundamentals.'
      },
      {
        title: 'HTML & CSS',
        content:
          'Build responsive web pages using HTML5, CSS3, Flexbox, Grid and modern responsive design techniques.'
      },
      {
        title: 'JavaScript',
        content:
          'Learn JavaScript fundamentals, DOM manipulation, events, functions, arrays, objects, asynchronous programming and APIs.'
      },
      {
        title: 'React',
        content:
          'Build modern frontend applications using React components, props, state, hooks, routing and API integration.'
      },
      {
        title: 'Spring Boot',
        content:
          'Learn Spring Boot application development, dependency injection, REST APIs, controllers, services and database integration.'
      },
      {
        title: 'REST APIs',
        content:
          'Understand REST architecture and create APIs that connect frontend applications with backend services.'
      },
      {
        title: 'MySQL',
        content:
          'Learn relational database concepts, SQL queries, joins, relationships, indexes and database integration.'
      },
      {
        title: 'Git & GitHub',
        content:
          'Learn version control, repositories, branches, commits, pull requests and collaborative development workflows.'
      },
      {
        title: 'Full Stack Project',
        content:
          'Develop a complete real-world full stack project integrating frontend, backend and database technologies.'
      }
    ]
  },

  {
    title: 'Python Full Stack',
    image: pythonFullStack,
    category: 'Full Stack',
    description:
      'Master full stack development with Python and modern web technologies.',
    topics: [
      'Python (Core & Advanced)',
      'Django / Flask',
      'HTML, CSS, JavaScript',
      'React (Frontend)',
      'Database (MySQL/PostgreSQL)'
    ],
    duration: '6 – 8 Months',
    level: 'Intermediate to Advanced',
    mode: 'Online + Live Classes',
    overview:
      'Learn complete full stack development using Python, modern frontend technologies, backend frameworks and databases.',
    modules: [
      {
        title: 'Advanced Python',
        content:
          'Strengthen Python programming skills and learn advanced concepts required for backend and application development.'
      },
      {
        title: 'HTML & CSS',
        content:
          'Create responsive and professional websites using HTML5 and CSS3.'
      },
      {
        title: 'JavaScript',
        content:
          'Learn JavaScript programming and browser-based application development.'
      },
      {
        title: 'React',
        content:
          'Build interactive frontend applications using React, components, hooks, routing and API integration.'
      },
      {
        title: 'Django / Flask',
        content:
          'Learn Python backend development using Django or Flask and create web applications and APIs.'
      },
      {
        title: 'REST APIs',
        content:
          'Create and consume REST APIs and connect frontend applications with backend services.'
      },
      {
        title: 'MySQL / PostgreSQL',
        content:
          'Learn relational database concepts, SQL queries, relationships and application database integration.'
      },
      {
        title: 'Authentication',
        content:
          'Understand login systems, authentication, authorization and secure application access.'
      },
      {
        title: 'Deployment',
        content:
          'Understand the fundamentals of deploying full stack applications to production environments.'
      },
      {
        title: 'Full Stack Project',
        content:
          'Build a complete real-world Python full stack application.'
      }
    ]
  },

  {
    title: 'MERN Stack Development',
    image: mernStack,
    category: 'Full Stack',
    description:
      'Build modern, scalable web applications using MongoDB, Express, React and Node.js.',
    topics: [
      'MongoDB',
      'Express.js',
      'React.js',
      'Node.js',
      'Full Stack Projects'
    ],
    duration: '6 – 8 Months',
    level: 'Intermediate to Advanced',
    mode: 'Online + Live Classes',
    overview:
      'Build modern production-ready web applications using the complete MERN technology stack.',
    modules: [
      {
        title: 'HTML & CSS',
        content:
          'Learn modern HTML and CSS and create responsive layouts for web applications.'
      },
      {
        title: 'JavaScript',
        content:
          'Learn modern JavaScript including ES6+, functions, objects, arrays, asynchronous programming and APIs.'
      },
      {
        title: 'React.js',
        content:
          'Create modern user interfaces using React components, hooks, routing and API integration.'
      },
      {
        title: 'Node.js',
        content:
          'Learn server-side JavaScript development and build backend applications using Node.js.'
      },
      {
        title: 'Express.js',
        content:
          'Create REST APIs, routes, middleware and backend services using Express.js.'
      },
      {
        title: 'MongoDB',
        content:
          'Learn NoSQL database concepts, collections, documents, queries and database integration.'
      },
      {
        title: 'REST APIs',
        content:
          'Build APIs that allow frontend and backend applications to communicate effectively.'
      },
      {
        title: 'Authentication',
        content:
          'Implement authentication, authorization and protected application routes.'
      },
      {
        title: 'Deployment',
        content:
          'Learn the basic workflow for deploying MERN applications.'
      },
      {
        title: 'MERN Projects',
        content:
          'Build complete real-world applications using MongoDB, Express.js, React and Node.js.'
      }
    ]
  },

  {
    title: 'Data Analyst',
    image: dataAnalytics,
    category: 'Data & Analytics',
    description:
      'Turn data into insights and make data-driven decisions.',
    topics: [
      'Excel (Advanced)',
      'SQL',
      'Python for Data Analysis',
      'Data Visualization (Power BI)',
      'Real-World Projects'
    ],
    duration: '3 – 5 Months',
    level: 'Beginner to Advanced',
    mode: 'Online + Live Classes',
    overview:
      'Learn how to collect, clean, analyze and visualize data to generate meaningful business insights.',
    modules: [
      {
        title: 'Advanced Excel',
        content:
          'Learn advanced formulas, functions, lookup operations, pivot tables, charts and data analysis techniques in Excel.'
      },
      {
        title: 'SQL',
        content:
          'Learn SQL queries, filtering, sorting, grouping, joins, subqueries and database analysis.'
      },
      {
        title: 'Python',
        content:
          'Learn Python programming concepts required for data analysis.'
      },
      {
        title: 'Pandas',
        content:
          'Use Pandas for data loading, cleaning, transformation, filtering and analysis.'
      },
      {
        title: 'NumPy',
        content:
          'Understand arrays, numerical operations and data processing using NumPy.'
      },
      {
        title: 'Data Cleaning',
        content:
          'Learn how to identify missing values, duplicates, incorrect formats and inconsistent data.'
      },
      {
        title: 'Data Analysis',
        content:
          'Analyze datasets and identify trends, patterns and useful business insights.'
      },
      {
        title: 'Power BI',
        content:
          'Create interactive dashboards and reports using Microsoft Power BI.'
      },
      {
        title: 'Data Visualization',
        content:
          'Present data clearly using charts, graphs and interactive dashboards.'
      },
      {
        title: 'Real-World Projects',
        content:
          'Work on practical datasets and build portfolio-ready data analysis projects.'
      }
    ]
  },

  {
    title: 'Generative AI',
    image: genaiLogo,
    category: 'Artificial Intelligence',
    badge: 'New',
    description:
      'Explore the next generation of AI and build intelligent solutions.',
    topics: [
      'AI & ML Fundamentals',
      'Prompt Engineering',
      'LLMs (ChatGPT, GPT)',
      'LangChain & Agents',
      'Real-World AI Projects'
    ],
    duration: '3 – 5 Months',
    level: 'Beginner to Advanced',
    mode: 'Online + Live Classes',
    overview:
      'Explore Generative AI, large language models, prompt engineering and AI agents while building practical AI applications.',
    modules: [
      {
        title: 'AI Fundamentals',
        content:
          'Understand Artificial Intelligence, its applications and the basic concepts behind intelligent systems.'
      },
      {
        title: 'Machine Learning Basics',
        content:
          'Learn the basic concepts of machine learning, datasets, models, training and evaluation.'
      },
      {
        title: 'Generative AI',
        content:
          'Understand how generative AI systems create text, images, code and other forms of content.'
      },
      {
        title: 'Prompt Engineering',
        content:
          'Learn how to write effective prompts and structure instructions for large language models.'
      },
      {
        title: 'LLMs',
        content:
          'Understand large language models, tokens, context, inference and practical LLM applications.'
      },
      {
        title: 'ChatGPT & GPT Models',
        content:
          'Explore practical applications of modern GPT-based AI systems and learn how to use them effectively.'
      },
      {
        title: 'LangChain',
        content:
          'Learn the fundamentals of building applications around language models using LangChain.'
      },
      {
        title: 'AI Agents',
        content:
          'Understand AI agents, tools, workflows and how agents can perform multi-step tasks.'
      },
      {
        title: 'RAG',
        content:
          'Learn Retrieval Augmented Generation and understand how applications can use external knowledge sources.'
      },
      {
        title: 'Real-World AI Projects',
        content:
          'Build practical Generative AI projects that can be demonstrated in a portfolio.'
      }
    ]
  }
];

const Courses = () => {
  const navigate = useNavigate();

  const [selectedCourse, setSelectedCourse] = useState(null);
  const [selectedModule, setSelectedModule] = useState(null);
  const [search, setSearch] = useState('');
  const [filter, setFilter] = useState('All');

  useEffect(() => {
    if (selectedCourse) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = '';
    }

    return () => {
      document.body.style.overflow = '';
    };
  }, [selectedCourse]);

  const categories = [
    'All',
    ...new Set(courseData.map(course => course.category))
  ];

  const filteredCourses = courseData.filter(course => {
    const searchText = search.toLowerCase();

    const matchesSearch =
      course.title.toLowerCase().includes(searchText) ||
      course.description.toLowerCase().includes(searchText) ||
      course.category.toLowerCase().includes(searchText);

    const matchesFilter =
      filter === 'All' || course.category === filter;

    return matchesSearch && matchesFilter;
  });

  const openCourse = course => {
    setSelectedCourse(course);
    setSelectedModule(course.modules[0]);
  };

  const closeCourse = () => {
    setSelectedCourse(null);
    setSelectedModule(null);
  };

  const styles = {
    page: {
      width: '100%',
      margin: 0,
      padding: 0,
      color: '#153c43',
      fontFamily: 'Inter, Arial, sans-serif',
      background: '#fff',
      overflow: 'hidden'
    },

    hero: {
      minHeight: '460px',
      position: 'relative',
      display: 'flex',
      alignItems: 'center',
      background:
        'linear-gradient(90deg,#034f51 0%,#075d5d 42%,rgba(5,75,76,.6) 65%,rgba(5,75,76,.25) 100%), url("https://images.unsplash.com/photo-1497366754035-f200968a6e72?auto=format&fit=crop&w=1800&q=90") center/cover no-repeat'
    },

    heroInner: {
      width: 'min(1180px, calc(100% - 48px))',
      margin: 'auto',
      position: 'relative',
      zIndex: 2
    },

    heroCopy: {
      width: '53%',
      padding: '55px 0'
    },

    heroSmall: {
      color: '#fff',
      fontSize: '12px',
      letterSpacing: '3px',
      fontWeight: 800,
      marginBottom: '12px'
    },

    heroHeading: {
      fontFamily: 'Georgia, "Times New Roman", serif',
      fontSize: '56px',
      lineHeight: '.98',
      margin: 0,
      color: '#fff',
      letterSpacing: '-1px'
    },

    heroGold: {
      color: '#edbd50'
    },

    heroDesc: {
      color: '#fff',
      fontSize: '15px',
      lineHeight: 1.55,
      maxWidth: '570px',
      margin: '17px 0 25px'
    },

    heroFeatures: {
      display: 'grid',
      gridTemplateColumns: 'repeat(4,1fr)',
      maxWidth: '500px'
    },

    heroFeature: {
      borderRight: '1px solid rgba(255,255,255,.35)',
      padding: '4px 20px 3px 5px',
      color: '#fff'
    },

    heroIcon: {
      fontSize: '27px',
      height: '35px',
      display: 'flex',
      alignItems: 'center'
    },

    heroFeatureText: {
      fontSize: '12px',
      lineHeight: 1.35,
      fontWeight: 600
    },

    section: {
      padding: '30px 0 35px',
      background: '#fff'
    },

    container: {
      width: 'min(1180px, calc(100% - 48px))',
      margin: 'auto'
    },

    label: {
      fontSize: '11px',
      fontWeight: 800,
      letterSpacing: '3px',
      color: '#075d60',
      marginBottom: '7px'
    },

    title: {
      fontFamily: 'Georgia, "Times New Roman", serif',
      fontSize: '43px',
      lineHeight: 1.08,
      margin: 0,
      color: '#103c43'
    },

    gold: {
      color: '#bd8b25'
    },

    searchFilter: {
      display: 'flex',
      gap: '12px',
      margin: '25px 0 20px',
      flexWrap: 'wrap'
    },

    searchBox: {
      flex: '1 1 350px',
      height: '48px',
      border: '1px solid #d4e5e2',
      borderRadius: '25px',
      padding: '0 20px',
      fontSize: '14px',
      outline: 'none',
      color: '#173e44',
      background: '#f8fcfb'
    },

    select: {
      flex: '0 1 230px',
      height: '48px',
      border: '1px solid #d4e5e2',
      borderRadius: '25px',
