      color: '#66777b',
      marginBottom: '15px'
    },

    grid: {
      display: 'grid',
      gridTemplateColumns: 'repeat(4,1fr)',
      gap: '10px'
    },

    card: {
      position: 'relative',
      minHeight: '390px',
      border: '1px solid #e1edeb',
      borderRadius: '11px',
      padding: '13px 16px',
      background: 'linear-gradient(145deg,#f4fbf9,#edf7f5)',
      display: 'flex',
      flexDirection: 'column',
      transition: '.25s ease'
    },

    badge: {
      position: 'absolute',
      right: '9px',
