      color: '#fff',
      fontSize: '10px',
      fontWeight: 800,
      zIndex: 2
    },

    newBadge: {
      background: '#efbe4b',
      color: '#163c42'
    },

    imageBox: {
      height: '125px',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      marginBottom: '5px'
    },

    courseImage: {
      maxWidth: '170px',
      maxHeight: '110px',
      width: 'auto',
      height: 'auto',
      objectFit: 'contain',
      borderRadius: '8px'
    },

    cardTitle: {
      fontFamily: 'Georgia, "Times New Roman", serif',
      color: '#113c43',
      fontSize: '19px',
      lineHeight: 1.1,
      margin: '3px 0 7px',
      fontWeight: 700
    },

    description: {
      color: '#53646a',
      fontSize: '12.5px',
      lineHeight: 1.42,
      minHeight: '52px',
      margin: '0 0 8px'
    },

    topics: {
      padding: 0,
      margin: 0,
      listStyle: 'none'
    },

    topic: {
      color: '#596b70',
      fontSize: '11.5px',
      lineHeight: 1.62,
      position: 'relative',
      paddingLeft: '23px'
    },

    check: {
      position: 'absolute',
      left: 0,
      top: '3px',
      width: '15px',
      height: '15px',
      borderRadius: '50%',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      background: '#08736e',
      color: '#fff',
      fontSize: '9px',
      fontWeight: 900
    },

    duration: {
      marginTop: 'auto',
      paddingTop: '8px',
      color: '#173e44',
      fontSize: '12px',
      fontWeight: 800,
      display: 'flex',
      alignItems: 'center',
      gap: '8px'
    },

    clock: {
      color: '#c79527',
      fontSize: '18px'
    },

    detailsBtn: {
      width: '100%',
      border: 0,
      borderRadius: '23px',
      background: '#075d5d',
      color: '#fff',
      height: '39px',
      marginTop: '9px',
      fontSize: '12px',
      fontWeight: 800,
      cursor: 'pointer'
    },

    empty: {
      gridColumn: '1 / -1',
      textAlign: 'center',
      padding: '50px 20px',
      border: '1px dashed #cbdedb',
      borderRadius: '12px',
      color: '#687a7d'
    },

    benefits: {
      width: 'min(1180px, calc(100% - 48px))',
      margin: 'auto',
      border: '1px solid #dcebea',
      borderRadius: '38px',
      minHeight: '72px',
      padding: '8px 14px',
      display: 'flex',
      alignItems: 'center',
      boxShadow: '0 6px 20px rgba(0,75,77,.06)',
      background: 'rgba(255,255,255,.96)'
    },

    benefitGrid: {
      flex: 1,
      display: 'grid',
      gridTemplateColumns: 'repeat(4,1fr)'
    },

    benefit: {
      display: 'flex',
      alignItems: 'center',
      gap: '10px',
      padding: '3px 14px',
      borderRight: '1px solid #d4e1df'
