    benefitIcon: {
      fontSize: '27px',
      color: '#075e60'
    },

    benefitText: {
      fontSize: '11px',
      lineHeight: 1.3,
      color: '#29454a'
    },

    startBtn: {
      border: 0,
      background: '#f0c354',
      color: '#173d42',
      borderRadius: '25px',
      height: '47px',
      padding: '0 21px',
      fontSize: '12px',
      fontWeight: 800,
      whiteSpace: 'nowrap',
      cursor: 'pointer'
