      justifyContent: 'center',
      padding: '20px'
    },

    modal: {
      width: 'min(900px,100%)',
      maxHeight: '90vh',
      overflowY: 'auto',
      borderRadius: '18px',
      background: '#fff',
      boxShadow: '0 25px 70px rgba(0,0,0,.3)'
    },

    modalHeader: {
      padding: '23px 25px 18px',
      background: 'linear-gradient(135deg,#075d5d,#0b7370)',
      color: '#fff',
      display: 'flex',
      justifyContent: 'space-between',
      gap: '20px',
      alignItems: 'flex-start'
    },

    modalTitle: {
      fontFamily: 'Georgia, "Times New Roman", serif',
      fontSize: '29px',
      margin: '0 0 7px'
    },

    modalDescription: {
      fontSize: '13px',
      lineHeight: 1.5,
      margin: 0,
      color: '#e7f5f3'
    },

    closeBtn: {
      width: '35px',
      height: '35px',
      flexShrink: 0,
      border: 0,
      borderRadius: '50%',
      background: 'rgba(255,255,255,.16)',
      color: '#fff',
      fontSize: '24px',
      cursor: 'pointer'
    },

    modalBody: {
      padding: '23px 25px'
    },

    moduleLayout: {
      display: 'grid',
      gridTemplateColumns: '260px 1fr',
      gap: '18px'
    },

    moduleList: {
      border: '1px solid #dce9e7',
      borderRadius: '10px',
      overflow: 'hidden',
      height: 'fit-content'
    },

    moduleHeading: {
      padding: '14px',
      background: '#075d5d',
      color: '#fff',
      fontSize: '14px',
      fontWeight: 800
    },

    moduleButton: {
      width: '100%',
      border: 0,
      borderBottom: '1px solid #e7efed',
      padding: '12px 13px',
      textAlign: 'left',
      background: '#fff',
      color: '#4b6165',
      fontSize: '12px',
      cursor: 'pointer'
    },

    moduleButtonActive: {
      background: '#eaf7f4',
      color: '#075d5d',
      fontWeight: 800,
      borderLeft: '4px solid #075d5d'
    },

    moduleContent: {
      border: '1px solid #dce9e7',
      borderRadius: '10px',
      padding: '22px',
      background: '#f8fcfb',
      minHeight: '300px'
    },

    moduleNumber: {
      fontSize: '11px',
      fontWeight: 800,
      color: '#c79527',
      letterSpacing: '1px',
      textTransform: 'uppercase',
      marginBottom: '8px'
    },

    moduleTitle: {
      fontFamily: 'Georgia, "Times New Roman", serif',
      color: '#103c43',
      fontSize: '25px',
      margin: '0 0 14px'
    },

    moduleText: {
      color: '#53646a',
      fontSize: '14px',
      lineHeight: 1.7,
      margin: 0
    },

    infoGrid: {
      display: 'grid',
      gridTemplateColumns: 'repeat(3,1fr)',
      gap: '10px',
      marginTop: '20px'
    },

    info: {
      border: '1px solid #dce9e7',
      borderRadius: '10px',
      padding: '13px',
      background: '#fff'
    },

    infoLabel: {
      fontSize: '10px',
      color: '#718084',
      textTransform: 'uppercase',
      letterSpacing: '1px'
    },

    infoValue: {
      fontSize: '13px',
      color: '#173e44',
      fontWeight: 800,
      marginTop: '4px'
    },

    modalFooter: {
      padding: '15px 25px 22px',
      display: 'flex',
      gap: '10px'
    },

    enquire: {
      flex: 1,
      border: 0,
      background: '#075d5d',
      color: '#fff',
      height: '43px',
      borderRadius: '22px',
      fontSize: '12px',
      fontWeight: 800,
      cursor: 'pointer'
    },

    modalClose: {
      border: '1px solid #d4a63b',
      background: '#fff',
      color: '#23474c',
      height: '43px',
      borderRadius: '22px',
      padding: '0 22px',
      fontSize: '12px',
      fontWeight: 800,
      cursor: 'pointer'
    }
  };

  return (
    <>
      <Header />

      <main style={styles.page}>

        {/* HERO */}
        <section style={styles.hero}>
          <div style={styles.heroInner}>
            <div style={styles.heroCopy}>
              <div style={styles.heroSmall}>OUR COURSES</div>

              <h1 style={styles.heroHeading}>
                Future-Ready
                <br />
                Skills for a
                <br />
                <span style={styles.heroGold}>Better Tomorrow</span>
              </h1>

              <p style={styles.heroDesc}>
                Industry-focused online courses designed to help you learn,
                build, and grow from anywhere in the world.
              </p>

              <div style={styles.heroFeatures}>

                <div style={styles.heroFeature}>
                  <div style={styles.heroIcon}>▣</div>
                  <div style={styles.heroFeatureText}>
                    Live
                    <br />
                    Classes
                  </div>
                </div>

                <div style={styles.heroFeature}>
                  <div style={styles.heroIcon}>♟</div>
                  <div style={styles.heroFeatureText}>
                    Expert
                    <br />
                    Trainers
                  </div>
                </div>

                <div style={styles.heroFeature}>
                  <div style={styles.heroIcon}>▤</div>
                  <div style={styles.heroFeatureText}>
                    Certification
                  </div>
                </div>

                <div style={{ ...styles.heroFeature, borderRight: 0 }}>
                  <div style={styles.heroIcon}>▥</div>
                  <div style={styles.heroFeatureText}>
                    Placement
                    <br />
                    Guidance
                  </div>
                </div>

              </div>
            </div>
          </div>
        </section>

        {/* COURSES */}
        <section style={styles.section}>
          <div style={styles.container}>

            <div style={styles.label}>
              EXPLORE OUR COURSES
            </div>

            <h2 style={styles.title}>
              Choose Your{' '}
              <span style={styles.gold}>
                Learning Path
              </span>
            </h2>

            {/* SEARCH + FILTER */}
            <div style={styles.searchFilter}>

              <input
                type="text"
                value={search}
                onChange={e => setSearch(e.target.value)}
                placeholder="🔍 Search courses..."
                style={styles.searchBox}
              />

              <select
                value={filter}
                onChange={e => setFilter(e.target.value)}
                style={styles.select}
              >
                {categories.map(category => (
                  <option key={category} value={category}>
                    {category}
                  </option>
                ))}
              </select>

            </div>

            <div style={styles.resultText}>
              Showing {filteredCourses.length} course
              {filteredCourses.length !== 1 ? 's' : ''}
            </div>

            {/* COURSE GRID */}
            <div style={styles.grid}>

              {filteredCourses.length === 0 ? (
                <div style={styles.empty}>
                  <h3>No courses found</h3>
                  <p>
                    Try another course name or select a different category.
                  </p>
                </div>
              ) : (
                filteredCourses.map((course, index) => (

                  <article
                    key={index}
                    style={styles.card}
                    onMouseEnter={e => {
                      e.currentTarget.style.transform =
                        'translateY(-4px)';
                      e.currentTarget.style.boxShadow =
                        '0 12px 25px rgba(4,77,78,.11)';
                    }}
                    onMouseLeave={e => {
                      e.currentTarget.style.transform = 'translateY(0)';
                      e.currentTarget.style.boxShadow = 'none';
                    }}
                  >

                    {course.badge && (
                      <span
                        style={{
                          ...styles.badge,
                          ...(course.badge === 'New'
                            ? styles.newBadge
                            : {})
                        }}
                      >
                        {course.badge}
                      </span>
                    )}

                    {/* LOCAL COURSE IMAGE */}
                    <div style={styles.imageBox}>
                      <img
                        src={course.image}
                        alt={course.title}
                        style={styles.courseImage}
                      />
                    </div>

                    <h3 style={styles.cardTitle}>
                      {course.title}
                    </h3>

                    <p style={styles.description}>
                      {course.description}
                    </p>

                    <ul style={styles.topics}>
                      {course.topics.map((topic, i) => (
                        <li key={i} style={styles.topic}>
                          <span style={styles.check}>✓</span>
                          {topic}
                        </li>
                      ))}
                    </ul>

                    <div style={styles.duration}>
                      <span style={styles.clock}>◷</span>
                      {course.duration}
                    </div>

                    <button
                      style={styles.detailsBtn}
                      onClick={() => openCourse(course)}
                    >
                      View Details&nbsp;&nbsp; →
                    </button>

                  </article>

                ))
              )}

            </div>
          </div>
        </section>

        {/* BENEFITS */}
        <section style={{ padding: '0 0 35px', background: '#fff' }}>
          <div style={styles.benefits}>

            <div style={styles.benefitGrid}>

              <div style={styles.benefit}>
                <div style={styles.benefitIcon}>▱</div>
                <div style={styles.benefitText}>
                  100% Online
                  <br />
                  Live Classes
                </div>
              </div>

              <div style={styles.benefit}>
                <div style={styles.benefitIcon}>♟</div>
                <div style={styles.benefitText}>
                  Learn from
                  <br />
                  Industry Experts
                </div>
              </div>

              <div style={styles.benefit}>
                <div style={styles.benefitIcon}>▣</div>
                <div style={styles.benefitText}>
                  Get Certified
                  <br />
                  & Showcase Your Skills
                </div>
              </div>

              <div
                style={{
                  ...styles.benefit,
                  borderRight: 0
                }}
              >
                <div style={styles.benefitIcon}>▥</div>
                <div style={styles.benefitText}>
                  Build a Career
                  <br />
                  with Confidence
                </div>
              </div>

            </div>

            <button
              style={styles.startBtn}
              onClick={() =>
                window.scrollTo({
                  top: 0,
                  behavior: 'smooth'
                })
              }
            >
              Start Learning Today&nbsp;&nbsp; →
            </button>

          </div>
        </section>

      </main>

      <Footer />

      {/* COURSE DETAILS MODAL */}
      {selectedCourse && (
        <div
          style={styles.backdrop}
          onMouseDown={e => {
            if (e.target === e.currentTarget) {
              closeCourse();
            }
          }}
        >

          <div style={styles.modal}>

            {/* MODAL HEADER */}
            <div style={styles.modalHeader}>

              <div>

                <h2 style={styles.modalTitle}>
                  {selectedCourse.title}
                </h2>

                <p style={styles.modalDescription}>
                  {selectedCourse.overview}
                </p>

              </div>

              <button
                style={styles.closeBtn}
                onClick={closeCourse}
              >
                ×
              </button>

            </div>

            {/* MODAL BODY */}
            <div style={styles.modalBody}>

              <div style={styles.moduleLayout}>

                {/* MODULE LIST */}
                <div style={styles.moduleList}>

                  <div style={styles.moduleHeading}>
                    Course Modules
                  </div>

                  {selectedCourse.modules.map((module, index) => {

                    const isActive =
                      selectedModule?.title === module.title;

                    return (
                      <button
                        key={index}
                        style={{
                          ...styles.moduleButton,
                          ...(isActive
                            ? styles.moduleButtonActive
                            : {})
                        }}
                        onClick={() => setSelectedModule(module)}
                      >
                        {index + 1}. {module.title}
                      </button>
                    );
                  })}

                </div>

                {/* MODULE CONTENT */}
                <div style={styles.moduleContent}>

                  {selectedModule && (
                    <>
                      <div style={styles.moduleNumber}>
                        Module {selectedCourse.modules.indexOf(
                          selectedModule
                        ) + 1}
                      </div>

                      <h3 style={styles.moduleTitle}>
                        {selectedModule.title}
                      </h3>

                      <p style={styles.moduleText}>
                        {selectedModule.content}
                      </p>
                    </>
                  )}

                </div>

              </div>

              {/* COURSE INFORMATION */}
              <div style={styles.infoGrid}>

                <div style={styles.info}>
                  <div style={styles.infoLabel}>
                    Duration
                  </div>
                  <div style={styles.infoValue}>
                    {selectedCourse.duration}
                  </div>
                </div>

                <div style={styles.info}>
                  <div style={styles.infoLabel}>
                    Level
                  </div>
                  <div style={styles.infoValue}>
                    {selectedCourse.level}
                  </div>
                </div>

                <div style={styles.info}>
                  <div style={styles.infoLabel}>
                    Training Mode
                  </div>
                  <div style={styles.infoValue}>
                    {selectedCourse.mode}
                  </div>
                </div>

              </div>

            </div>

            {/* MODAL FOOTER */}
            <div style={styles.modalFooter}>

              <button
                style={styles.enquire}
                onClick={() => navigate('/contact')}
              >
                Enquire Now&nbsp;&nbsp; →
              </button>

              <button
                style={styles.modalClose}
                onClick={closeCourse}
              >
                Close
              </button>

            </div>

          </div>

        </div>
      )}

    </>
  );
};

export default Courses;
